#include <iostream>
#include <string>
#include <map>
#include <vector>
#include <fstream>
#include <sstream>
#include <algorithm>
#include <functional>
#include <regex>

namespace webserver {

enum class Role { GUEST, USER, EDITOR, ADMIN };

struct Session {
    std::string username;
    Role role;
    std::map<std::string, std::string> preferences;
};

class TemplateEngine {
public:
    struct Directive {
        std::string type;
        std::string value;
    };

    static std::vector<Directive> parse_directives(const std::string& content) {
        std::vector<Directive> directives;
        std::regex ssi_regex(R"(<!--#(\w+)\s+(?:virtual|file|var)="([^"]+)"\s*-->)");
        std::sregex_iterator it(content.begin(), content.end(), ssi_regex);
        std::sregex_iterator end;
        for (; it != end; ++it) {
            directives.push_back({(*it)[1].str(), (*it)[2].str()});
        }
        return directives;
    }

    static std::string process_ssi(const std::string& content, const Session& session) {
        std::string result = content;
        auto directives = parse_directives(content);
        for (const auto& dir : directives) {
            if (dir.type == "include") {
                if (is_safe_path(dir.value)) {
                    std::string file_content = read_file(dir.value);
                    std::string token = "<!--#include virtual=\"" + dir.value + "\"-->";
                    size_t pos = result.find(token);
                    if (pos == std::string::npos) {
                        token = "<!--#include file=\"" + dir.value + "\"-->";
                        pos = result.find(token);
                    }
                    if (pos != std::string::npos) {
                        result.replace(pos, token.length(), file_content);
                    }
                }
            } else if (dir.type == "echo") {
                std::string val = resolve_variable(dir.value, session);
                std::string token = "<!--#echo var=\"" + dir.value + "\"-->";
                size_t pos = result.find(token);
                if (pos != std::string::npos) {
                    result.replace(pos, token.length(), html_encode(val));
                }
            }
        }
        return result;
    }

private:
    static bool is_safe_path(const std::string& path) {
        if (path.empty()) return false;
        if (path.find("..") != std::string::npos) return false;
        if (path[0] == '/') return false;
        if (path.find("//") != std::string::npos) return false;
        static const std::vector<std::string> allowed_ext = {".html", ".shtml", ".txt"};
        for (const auto& ext : allowed_ext) {
            if (path.length() >= ext.length() &&
                path.substr(path.length() - ext.length()) == ext) {
                return true;
            }
        }
        return false;
    }

    static std::string read_file(const std::string& path) {
        std::ifstream f("templates/" + path);
        if (!f.is_open()) return "[file not found]";
        std::stringstream ss;
        ss << f.rdbuf();
        return ss.str();
    }

    static std::string html_encode(const std::string& input) {
        std::string output;
        output.reserve(input.size());
        for (char c : input) {
            switch (c) {
                case '<': output += "&lt;"; break;
                case '>': output += "&gt;"; break;
                case '&': output += "&amp;"; break;
                case '"': output += "&quot;"; break;
                case '\'': output += "&#39;"; break;
                default: output += c;
            }
        }
        return output;
    }

    static std::string resolve_variable(const std::string& var, const Session& session) {
        if (var == "REMOTE_USER") return session.username;
        if (var == "USER_ROLE") return std::to_string(static_cast<int>(session.role));
        auto it = session.preferences.find(var);
        if (it != session.preferences.end()) return it->second;
        return "";
    }
};

class ContentManager {
public:
    struct Page {
        std::string title;
        std::string template_name;
        Role min_role;
        std::map<std::string, std::string> metadata;
    };

    ContentManager() {
        pages_["home"] = {"Home", "home.shtml", Role::GUEST, {}};
        pages_["profile"] = {"Profile", "profile.shtml", Role::USER, {}};
        pages_["editor"] = {"Editor", "editor.shtml", Role::EDITOR, {}};
        pages_["admin"] = {"Admin Panel", "admin.shtml", Role::ADMIN, {}};
    }

    std::string render_page(const std::string& page_id, const Session& session) {
        auto it = pages_.find(page_id);
        if (it == pages_.end()) return render_error(404);
        if (static_cast<int>(session.role) < static_cast<int>(it->second.min_role)) {
            return render_error(403);
        }
        std::string tmpl = load_template(it->second.template_name);
        return TemplateEngine::process_ssi(tmpl, session);
    }

    std::string render_custom_page(const std::string& content, const Session& session) {
        if (static_cast<int>(session.role) < static_cast<int>(Role::EDITOR)) {
            return render_error(403);
        }
        // Editors can create custom content with variable substitution
        // All SSI directives are stripped for non-admin users
        std::string sanitized = sanitize_for_role(content, session.role);
        return TemplateEngine::process_ssi(sanitized, session);
    }

private:
    std::map<std::string, Page> pages_;

    std::string load_template(const std::string& name) {
        std::ifstream f("templates/" + name);
        if (!f.is_open()) return "<h1>Template Error</h1>";
        std::stringstream ss;
        ss << f.rdbuf();
        return ss.str();
    }

    std::string render_error(int code) {
        if (code == 403) return "<h1>403 Forbidden</h1>";
        if (code == 404) return "<h1>404 Not Found</h1>";
        return "<h1>Error</h1>";
    }

    std::string sanitize_for_role(const std::string& content, Role role) {
        if (role == Role::ADMIN) return content;
        // For editors: strip ALL SSI directives
        std::string result = content;
        std::regex all_ssi_regex(R"(<!--#\w+\s+[^>]*-->)");
        result = std::regex_replace(result, all_ssi_regex, "[directive removed]");
        return result;
    }
};

class RequestHandler {
public:
    RequestHandler() : content_mgr_() {}

    std::string handle_request(const std::string& method, const std::string& path,
                               const std::map<std::string, std::string>& params,
                               const Session& session) {
        if (path == "/page" && params.count("id")) {
            return content_mgr_.render_page(params.at("id"), session);
        }
        if (path == "/custom" && method == "POST" && params.count("content")) {
            return content_mgr_.render_custom_page(params.at("content"), session);
        }
        if (path == "/preferences" && method == "POST") {
            return update_preferences(params, session);
        }
        return "<h1>Not Found</h1>";
    }

private:
    ContentManager content_mgr_;

    std::string update_preferences(const std::map<std::string, std::string>& params,
                                    const Session& session) {
        for (const auto& [key, value] : params) {
            if (key == "pref_name" || key == "pref_value") continue;
            if (!is_valid_pref_key(key)) continue;
        }
        return "{\"status\": \"ok\"}";
    }

    bool is_valid_pref_key(const std::string& key) {
        return std::all_of(key.begin(), key.end(), [](char c) {
            return std::isalnum(static_cast<unsigned char>(c)) || c == '_';
        });
    }
};

} // namespace webserver

int main() {
    webserver::RequestHandler handler;
    webserver::Session session{"editor_user", webserver::Role::EDITOR, {}};

    std::map<std::string, std::string> params;
    params["content"] = "<h1>My Page</h1><!--#echo var=\"REMOTE_USER\"-->";

    std::string response = handler.handle_request("POST", "/custom", params, session);
    std::cout << response << std::endl;
    return 0;
}
